import { createClient, httpLink } from "@pyrpc/client";
import type { Types } from "@pyrpc/types";

// The rule engine lives in the FastAPI backend: api/core/rule/rules.py
// Types for `client` come from web/__pyrpc.ts, generated by
// `uv run pyrpc codegen main --client ../web` inside api/.
export const apiUrl = process.env.API_URL ?? "http://127.0.0.1:8000";

export const client = createClient<Types>({
  links: [httpLink({ url: apiUrl })],
});
